    /// Starts the sessions the macrostep's entries deferred (W3C SCXML 6.4), now that
    /// the macrostep is over.
    public func executePendingInvokes(engine: Engine<InvokeCandidateSelectsTheChildPolicy>) {
        SceRuntime.executePendingInvokes(&pendingInvokes) { pending in
            if pending.documentID.utf8.elementsEqual("_invoke_0".utf8) {
                sceStartInvokeInvoke0(pending, engine: engine)
                return
            }
        }
    }

    /// Starts the session of `<invoke srcexpr>` `_invoke_0` (W3C SCXML 6.4): the
    /// value `srcexpr` computes names, by its document stem, one of the candidates the
    /// invoke declares (docs/SCE_ACCEPTED_SUBSET.md §2.13), which is the one started.
    private func sceStartInvokeInvoke0(_ pending: PendingInvoke<InvokeCandidateSelectsTheChildState>, engine: Engine<InvokeCandidateSelectsTheChildPolicy>) {
        // §scxml-6.4: the `srcexpr` is read now, as the invocation starts, so what the
        // entry actions of the state left is what it names. One that cannot be
        // evaluated is an attribute that cannot be: `error.execution`, and nothing starts.
        // Under `datamodel="ecmascript"` the engine reads it, as ECMAScript converts the value
        // to a string, and the arguments are read only for the candidate it chose (6.4.3).
        guard let sceValue = evaluateText("pick") else {
            engine.raise(EventWithMetadata.platformError(InvokeCandidateSelectsTheChildEvent.errorExecution, message: "<invoke srcexpr> could not be evaluated"))
            return
        }
        let sceSelected = documentStem(sceValue)
        // W3C SCXML C.1: the child is known by the id its parent mints for it.
        let childSessionID = "\(sessionID).\(pending.invokeID)"
        let sceStarted: any ChildEngine
        if sceSelected.utf8.elementsEqual("chosen".utf8) {
            // The stem names the document the build wrote a child for, and its
            // arguments are read only now that the value has chosen it (6.4.3).
            let childPolicy = ChosenPolicy()

            let session = InvokedSession(
                policy: childPolicy,
                sessionID: childSessionID,
                queue: ParentEventQueue(parentSessionID: sessionID)
            )
            session.engine.setClock(engine.clock())
            // SCE_MESH.md §21.3: the child's router is the one the factory answers for this
            // invoke and this document, installed before the child initializes.
            engine.startChildMesh(of: session, invokeID: "_invoke_0", document: "chosen")
            sceStarted = session
        } else if sceSelected.utf8.elementsEqual("other".utf8) {
            // The stem names the document the build wrote a child for, and its
            // arguments are read only now that the value has chosen it (6.4.3).
            let childPolicy = OtherPolicy()

            let session = InvokedSession(
                policy: childPolicy,
                sessionID: childSessionID,
                queue: ParentEventQueue(parentSessionID: sessionID)
            )
            session.engine.setClock(engine.clock())
            // SCE_MESH.md §21.3: the child's router is the one the factory answers for this
            // invoke and this document, installed before the child initializes.
            engine.startChildMesh(of: session, invokeID: "_invoke_0", document: "other")
            sceStarted = session
        } else {
            // A value naming none of the declared candidates is the failure the
            // Interpreter reports when a document will not load: nothing is created,
            // and, as there, the arguments are not read.
            engine.raise(EventWithMetadata.platformError(InvokeCandidateSelectsTheChildEvent.errorExecution, message: "<invoke srcexpr> evaluated to a document it did not declare"))
            return
        }
        // W3C SCXML 6.4.1: tracked before the child initializes.
        activeInvokes["_invoke_0"] = ChildSession(
            sessionID: childSessionID,
            invokeID: "_invoke_0",
            parentSessionID: sessionID,
            autoforward: false,
            finalizeScript: ""
        )
        sceStarted.initialize()
        sceInvokeChildInvoke0 = sceStarted
        sceInvokeStemInvoke0 = sceSelected
        sceSettleInvokeInvoke0(engine: engine)
    }

    /// Takes what the session of `<invoke>` `_invoke_0` sent this machine, and
    /// raises `done.invoke` once it has ended (W3C SCXML 5.5 + 6.3.1: with the donedata its
    /// top-level `<final>` stashed).
    private func sceSettleInvokeInvoke0(engine: Engine<InvokeCandidateSelectsTheChildPolicy>) {
        guard let child = sceInvokeChildInvoke0, !sceInvokeDoneInvoke0 else {
            return
        }
        drainAndRaiseChildEvents(
            childEngine: child,
            activeInvokes: activeInvokes,
            invokeKey: "_invoke_0",
            engine: engine
        )
        if child.isInFinalState {
            sceInvokeDoneInvoke0 = true
            // SCE_MESH.md §21.5: the session reached its top-level `<final>`, so its router
            // is told once.
            child.detachMesh()
            raiseDoneInvoke(invokeID: "_invoke_0", donedata: child.donedataAtFinal, engine: engine)
        }
    }

    /// Ticks the running sessions (W3C SCXML 6.4): what a child sent before is taken
    /// first, then the child takes its turn, then what it sent in it.
    public func tickChildren(engine: Engine<InvokeCandidateSelectsTheChildPolicy>) {
        if !sceInvokeDoneInvoke0, let child = sceInvokeChildInvoke0 {
            drainAndRaiseChildEvents(
                childEngine: child,
                activeInvokes: activeInvokes,
                invokeKey: "_invoke_0",
                engine: engine
            )
            child.applyMeshCalls()
            child.tick()
            sceSettleInvokeInvoke0(engine: engine)
        }
    }

    /// Settles what every running child sent this machine while a delivery drove it
    /// (docs/adr/0045): one body for every drive of a child, so a save at any boundary
    /// of this session finds its buffer empty.
    public func settleChildren(engine: Engine<InvokeCandidateSelectsTheChildPolicy>) {
        sceSettleInvokeInvoke0(engine: engine)
    }

    /// The nearest deadline of a running child (W3C SCXML 6.4), so a host that walks
    /// time by `timeUntilNextScheduled` does not step over a timer a child armed. A
    /// child that has ended is skipped: the policy keeps it until its state exits, and
    /// what it armed is no longer owed.
    public func nextChildDeadline() -> Duration? {
        var soonest: Duration?
        if !sceInvokeDoneInvoke0, let due = sceInvokeChildInvoke0?.timeUntilNextScheduled() {
            soonest = soonest.map { min($0, due) } ?? due
        }
        return soonest
    }

    /// Delivers a delayed `<send target="#_<invokeid>">` whose wait is over, by name:
    /// a child need not declare every event its parent sends (W3C SCXML 6.2 + 6.4).
    /// Whether the invocation was there to take it: one whose session has reached its
    /// final state has ended, and the engine reports the send it could not deliver
    /// (W3C SCXML C.1).
    public func deliverToInvocation(invokeID: String, eventName: String, eventData: String, sendID: String) -> Bool {
        if invokeID.utf8.elementsEqual("_invoke_0".utf8) {
            if let child = sceInvokeChildInvoke0, !child.isInFinalState {
                deliverToChild(child, eventName: eventName, eventData: eventData, sender: sessionID)
                return true
            }
            return false
        }
        return false
    }

    /// Whether `#_<invokeid>` names an invocation running now (W3C SCXML 6.4 + C.1):
    /// one whose session has reached its final state has ended, and a send naming it
    /// is reported when it is made.
    public func isInvocationRunning(_ invokeID: String) -> Bool {
        if invokeID.utf8.elementsEqual("_invoke_0".utf8) {
            return sceInvokeChildInvoke0.map { !$0.isInFinalState } ?? false
        }
        return false
    }

    /// Whether a session id names a child of this machine that is running now
    /// (W3C SCXML C.1): the test `deliverToChildSession` makes.
    public func isChildSessionRunning(_ childSessionID: String) -> Bool {
        if childSessionID.isEmpty {
            return false
        }
        if let session = activeInvokes["_invoke_0"], session.sessionID.utf8.elementsEqual(childSessionID.utf8) {
            return sceInvokeChildInvoke0.map { !$0.isInFinalState } ?? false
        }
        return false
    }

    /// Delivers an event addressed to a child's published location (W3C SCXML C.1).
    /// The parent mints `parentSession.invokeId` for each child and that id is what the
    /// child's `_ioprocessors` entry names, so a `<send>` whose target decodes to one of
    /// them is addressed to that child and not to this machine. False names no live
    /// child of ours, and the event takes the ordinary external path.
    public func deliverToChildSession(childSessionID: String, eventName: String, eventData: String) -> Bool {
        if !isChildSessionRunning(childSessionID) {
            return false
        }
        if let session = activeInvokes["_invoke_0"], session.sessionID.utf8.elementsEqual(childSessionID.utf8),
           let child = sceInvokeChildInvoke0 {
            deliverToChild(child, eventName: eventName, eventData: eventData, sender: sessionID)
            return true
        }
        return false
    }


    /// Enters one state (W3C SCXML 3.8): adds it to the configuration, runs its
    /// `<onentry>`, and its `<initial>` transition's content when its initial
    /// state is entered by default.
    public func executeEntryActions(_ state: InvokeCandidateSelectsTheChildState, engine: Engine<InvokeCandidateSelectsTheChildPolicy>, isDefaultEntry: Bool) {
        switch state {
        case .probe:
            // W3C SCXML 6.4: an <invoke> starts at the end of the macrostep, so its
            // entry is deferred, and a state that exits before then never starts it.
            do {
                sceInvokeStartsInvoke0 += 1
                let generatedInvokeID = "probe.\(sceInvokeStartsInvoke0)._invoke_0"
                deferInvoke(&pendingInvokes, PendingInvoke(
                    invokeID: generatedInvokeID,
                    state: .probe,
                    documentID: "_invoke_0"
                ))
            }
        default:
            break  // No entry actions
        }
    }

    /// Runs a `<history>`'s default transition content (W3C SCXML 3.10.2), after
    /// its parent's onentry (and after the parent's own `<initial>` content) when
    /// the history was taken with nothing recorded. The engine asks for it by the
    /// entry set's defaultHistoryContent answer; a history that restored what it
    /// recorded runs nothing.
    public func executeHistoryDefaultContent(_ history: HistoryID, engine: Engine<InvokeCandidateSelectsTheChildPolicy>) {
        // W3C SCXML 3.10.2: no <history> in this document has default content.
    }

    /// Exits one state (W3C SCXML 3.9): records its histories, runs its `<onexit>`,
    /// cancels its invocations and removes it from the configuration, in
    /// §scxml-D-exitStates's order.
    public func executeExitActions(_ state: InvokeCandidateSelectsTheChildState, engine: Engine<InvokeCandidateSelectsTheChildPolicy>, configurationBeforeExit: [InvokeCandidateSelectsTheChildState]) {
        // §scxml-D-exitStates orders one state's exit as onexit, then cancelInvoke,
        // then configuration.delete(s), so `In(s)` inside s's own handler is true:
        // the <onexit> switch comes first and the removal from the configuration
        // last.
        switch state {
        default:
            break  // No exit actions
        }
        // W3C SCXML 6.4: the invocations of an exited state end with it: one not yet
        // started never starts, and a running session is exited, its states' <onexit>
        // run, before it is dropped. What that exit sends to #_parent is dropped with
        // it (test252).
        switch state {
        case .probe:
            cancelInvokesForState(&pendingInvokes, .probe)
            sceInvokeChildInvoke0?.stop()
            sceInvokeChildInvoke0?.detachMesh()
            sceInvokeChildInvoke0 = nil
            activeInvokes["_invoke_0"] = nil
            sceInvokeDoneInvoke0 = false
        default:
            break  // No invocations to cancel
        }
    }



    /// Appendix D selectTransitions, the half only this document can answer: the
    /// first of `state`'s own transitions, in document order, that `event` enables
    /// and whose guard holds. The engine walks the atomic states and their
    /// ancestors and keeps the ordered set; the null event asks for eventless
    /// transitions.
    public func firstEnabledTransition(
        _ state: InvokeCandidateSelectsTheChildState,
        event: InvokeCandidateSelectsTheChildEvent,
        engine: Engine<InvokeCandidateSelectsTheChildPolicy>
    ) -> EnabledTransition<InvokeCandidateSelectsTheChildState>? {
        switch state {
        case .probe:
            if event == .fromChosen {
                do {
                    return EnabledTransition(
                        source: state,
                        targets: [.state(.pass)],
                        transitionIndex: 0,
                        hasActions: false,
                        isInternal: false
                    )
                }
            }
            if event == .fromOther {
                do {
                    return EnabledTransition(
                        source: state,
                        targets: [.state(.wrongChild)],
                        transitionIndex: 1,
                        hasActions: false,
                        isInternal: false
                    )
                }
            }
            if event == .errorExecution {
                do {
                    return EnabledTransition(
                        source: state,
                        targets: [.state(.noChild)],
                        transitionIndex: 2,
                        hasActions: false,
                        isInternal: false
                    )
                }
            }
        default:
            break
        }
        return nil
    }

    /// Runs one transition's executable content (W3C SCXML 3.13), between the
