    public func executeTransitionContent(source: InvokeCandidateSelectsTheChildState, transitionIndex: Int, engine: Engine<InvokeCandidateSelectsTheChildPolicy>) {
        // W3C SCXML 3.13: no transition in this document has content.
    }}
